insert into app_private.ws_notices values ('standard_unconfirmed', 'Standard unconfirmed', 'The exact event path into Watchful is being confirmed right now by a read-only check. On 11/27, 13 working cameras (Helios 010 and 011 Cams 1-3, Rangers 011, 012, 017 and 028, Solar Spotter 235 Cams 1, 2 and 4) sent events while both motion and intrusion were turned off. So motion and intrusion email are not the only way events reach Watchful. Until the check finishes, the event items describe what working units have in common. They are not a proven recipe.');
insert into app_private.ws_notices values ('evidence_upload', 'Before you upload', 'Cover or crop any password, token, IP address or serial number.');
